for (size_t i = start; i < end; i++) {
    Particle* particle = &particles[i];
    glm::ivec3 cell = getCell(particle, settings.h);
    float density = selfDens;
    float pressure = 0.0f;

    // Check 27 neighboring cells
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                uint32_t neighborHash = getHash(neighborCell);

                // Iterate through particles in this cell
                for (size_t j = particleTable[neighborHash];
                     j < particleTable[neighborHash + 1]; j++) {
                    Particle* neighbor = &particles[j];
                    if (i == j) continue; // Skip self

                    glm::vec3 r = neighbor->position - particle->position;
                    float r2 = glm::dot(r, r);
                    float r = std::sqrt(r2);

                    if (r < h) {
                        float kernel = poly6 * std::pow(h2 - r2, 3);
                        density += mass * kernel;
                    }
                }
            }
        }
    }

    // Calculate pressure using Tait equation
    if (density > 0.0f) {
        pressure = (gasConstant * (std::pow(density / restDensity, 7) - 1.0f)) / restDensity;
    }

    particle->density = density;
    particle->pressure = pressure;
}

